"""Runtime metric registry — loaded from src/finengine/data/metrics.json.

The JSON is a DERIVED aggregate of the six per-cell registries
(`src/finengine/data/registry/<cell>.json`), generated by
`src/finengine/data/build_metrics_json.py`. Edit the per-cell registry, run the
generator, redeploy. (The old Excel→metrics.json path is archived under
`archive/old_registry_source/`.)

Counts as of 2026-07-14:
- Extractable: 91 non-financial / 80 bank
- Calculated:  47 non-financial / 28 bank
"""
from __future__ import annotations

import json
from pathlib import Path

from finengine.models.document import DocType, ProcessingMode

_DATA_PATH = Path(__file__).resolve().parent.parent / "data" / "metrics.json"

with _DATA_PATH.open("r", encoding="utf-8") as _f:
    _RAW = json.load(_f)


def _extractable_list(items: list[dict]) -> list[dict]:
    """Shape items for runtime: dict with enum, name_ru, name_en, aliases_ru,
    aliases_en, description, hint, period_type, formula_default_abs_behavior,
    standard, role, document_types."""
    out: list[dict] = []
    for it in items:
        out.append(
            {
                "enum": it["enum"],
                "name_ru": it["name_ru"],
                "name_en": it.get("name_en", ""),
                "aliases_ru": it.get("aliases_ru") or [],
                "aliases_en": it.get("aliases_en") or [],
                "description": it.get("description", ""),
                "hint": it.get("hint", ""),
                "standard": it.get("standard", ""),
                "role": it.get("role", ""),
                "value_basis": it.get("value_basis"),
                "period_type": it.get("period_type", ""),
                "formula_default_abs_behavior": bool(it.get("formula_default_abs_behavior", False)),
                "document_types": it.get("document_types") or ["financial_report"],
            }
        )
    return out


def _calculated_list(items: list[dict]) -> list[tuple[str, str, str, list[str]]]:
    """Existing call-sites expect tuples (enum, name_ru, formula, deps)."""
    return [(it["enum"], it["name_ru"], it.get("formula", ""), it.get("deps", []) or []) for it in items]


_SOURCE_SCOPED_DOCUMENT_TYPES = {
    DocType.FINANCIAL_REPORT.value,
    DocType.PRESS_RELEASE.value,
    DocType.TRANSCRIPT.value,
    DocType.PRESENTATION.value,
    DocType.EQUITY_RESEARCH.value,
}

STRUCTURED_METRIC_DOCUMENT_TYPES = frozenset(
    {
        DocType.FINANCIAL_REPORT,
        DocType.PRESS_RELEASE,
        DocType.EQUITY_RESEARCH,
    }
)

METRIC_PROCESSING_MODES = frozenset(
    {
        ProcessingMode.FINANCIAL_REPORTING,
        ProcessingMode.RESULTS_MATERIAL,
    }
)


def processing_mode_for_document(document: object) -> ProcessingMode:
    """Read the purpose mode, with a narrow bridge for v2 metadata."""
    version = int(getattr(document, "classification_version", 0) or 0)
    if version >= 3:
        raw_mode = getattr(
            document,
            "processing_mode",
            ProcessingMode.NARRATIVE,
        )
        try:
            return ProcessingMode(
                str(getattr(raw_mode, "value", raw_mode) or "").lower()
            )
        except ValueError:
            return ProcessingMode.NARRATIVE
    if version >= 2 and hasattr(document, "metric_scope"):
        raw_mode = getattr(document, "metric_scope")
        try:
            return ProcessingMode(
                str(getattr(raw_mode, "value", raw_mode) or "").lower()
            )
        except ValueError:
            pass

    raw_type = getattr(document, "doc_type", DocType.OTHER)
    try:
        doc_type = DocType(str(getattr(raw_type, "value", raw_type) or "").lower())
    except ValueError:
        return ProcessingMode.NARRATIVE
    if doc_type == DocType.FINANCIAL_REPORT:
        return ProcessingMode.FINANCIAL_REPORTING
    if doc_type in {DocType.PRESS_RELEASE, DocType.PRESENTATION}:
        return ProcessingMode.RESULTS_MATERIAL
    return ProcessingMode.NARRATIVE


def supports_metric_extraction(processing_mode: object) -> bool:
    """Return whether registry-backed Metrics are available in this mode."""
    value = getattr(processing_mode, "value", processing_mode)
    try:
        normalized = ProcessingMode(str(value or "").strip().lower())
    except ValueError:
        return False
    return normalized in METRIC_PROCESSING_MODES


def canonical_document_type_for_processing_mode(processing_mode: object) -> str:
    """Map a purpose mode to the existing registry source buckets."""
    value = getattr(processing_mode, "value", processing_mode)
    try:
        normalized = ProcessingMode(str(value or "").strip().lower())
    except ValueError:
        normalized = ProcessingMode.NARRATIVE
    if normalized == ProcessingMode.RESULTS_MATERIAL:
        return DocType.PRESS_RELEASE.value
    return DocType.FINANCIAL_REPORT.value


def extractable_for_processing_mode(
    metrics: list[dict], processing_mode: object
) -> list[dict]:
    """Filter registry rows for financial reporting or results materials."""
    if not supports_metric_extraction(processing_mode):
        return []
    return extractable_for_document_type(
        metrics,
        canonical_document_type_for_processing_mode(processing_mode),
    )


def supports_structured_metric_extraction(document_type: object) -> bool:
    """Return whether a source belongs in the tabular metric workflow."""
    value = getattr(document_type, "value", document_type)
    try:
        normalized = DocType(str(value or "").strip().lower())
    except ValueError:
        return False
    return normalized in STRUCTURED_METRIC_DOCUMENT_TYPES


def canonical_metric_document_type(document_type: object) -> str:
    """Normalize extraction scope, preserving report behavior as fallback."""
    value = getattr(document_type, "value", document_type)
    normalized = str(value or "").strip().lower()
    if normalized in _SOURCE_SCOPED_DOCUMENT_TYPES:
        return normalized
    return DocType.FINANCIAL_REPORT.value


def extractable_for_document_type(
    metrics: list[dict], document_type: object
) -> list[dict]:
    """Return registry rows explicitly enabled for this source type."""
    normalized = canonical_metric_document_type(document_type)
    return [
        metric
        for metric in metrics
        if normalized in (metric.get("document_types") or [DocType.FINANCIAL_REPORT.value])
    ]


def source_relevant_calculated_defs(
    calculated_defs: list[tuple], extractable: list[dict]
) -> list[tuple]:
    """Keep calculations whose complete dependency chain is source-available.

    An extractable enum owns its output whenever both registry forms exist.
    Calculated-only enums are admitted iteratively once all dependencies are
    reachable from source-scoped extractables or an earlier calculation.
    """
    available = {
        str(metric.get("enum") or "").strip().upper()
        for metric in extractable
        if metric.get("enum")
    }
    pending = [
        definition
        for definition in calculated_defs
        if definition and str(definition[0]).strip().upper() not in available
    ]
    selected: list[tuple] = []

    while pending:
        admitted: list[tuple] = []
        for definition in pending:
            deps = {
                str(dep).strip().upper()
                for dep in (definition[3] or [])
                if str(dep).strip()
            }
            if deps and deps <= available:
                admitted.append(definition)
        if not admitted:
            break
        for definition in admitted:
            pending.remove(definition)
            selected.append(definition)
            available.add(str(definition[0]).strip().upper())

    return selected


EXTRACTABLE_NON_FINANCIAL = _extractable_list(_RAW["extractable"]["non_financial"])
EXTRACTABLE_BANK = _extractable_list(_RAW["extractable"]["bank"])
CALCULATED_NON_FINANCIAL = _calculated_list(_RAW["calculated"]["non_financial"])
CALCULATED_BANK = _calculated_list(_RAW["calculated"]["bank"])

# Quick lookup dict by enum → metric meta. Useful for prompt building.
NF_BY_ENUM = {m["enum"]: m for m in EXTRACTABLE_NON_FINANCIAL}
BANK_BY_ENUM = {m["enum"]: m for m in EXTRACTABLE_BANK}
METRIC_NAME_EN_BY_ENUM = {
    item["enum"]: item.get("name_en", "")
    for group in ("non_financial", "bank")
    for kind in ("extractable", "calculated")
    for item in _RAW[kind][group]
    if item.get("enum") and item.get("name_en")
}
METRIC_PERIOD_TYPE_BY_ENUM = {
    m["enum"]: m.get("period_type", "")
    for m in [*EXTRACTABLE_NON_FINANCIAL, *EXTRACTABLE_BANK]
}
